do $$
begin
  if not exists (select 1 from cfr_app.workspaces where id = 'phase1-golden-a' and owner_user_id = 'sha256:671c807a45b39b1c350c4a7c0337b73ae3654f1c2a09d5206c2bf03f643b6c67')
    or not exists (select 1 from cfr_app.workspaces where id = 'phase1-golden-b' and owner_user_id = 'sha256:27b97516a874758dff11be9787b7a5a9fea3367b202f821aedd1bc86a0e454ff')
    or not exists (select 1 from cfr_app.workspace_members where workspace_id = 'phase1-golden-a' and user_id = 'sha256:671c807a45b39b1c350c4a7c0337b73ae3654f1c2a09d5206c2bf03f643b6c67' and role = 'owner')
    or not exists (select 1 from cfr_app.workspace_members where workspace_id = 'phase1-golden-b' and user_id = 'sha256:27b97516a874758dff11be9787b7a5a9fea3367b202f821aedd1bc86a0e454ff' and role = 'owner')
  then raise exception 'golden workspace binding mismatch'; end if;
  if (select count(*) from cfr_app.case_recorded_events
      where workspace_id = 'phase1-golden-a' and scenario_id = 'golden-mobile-checkout-v1') <> 56
    or (select md5(string_agg(id || ':' || content_hash, '|' order by id))
      from cfr_app.case_recorded_events where workspace_id = 'phase1-golden-a'
        and scenario_id = 'golden-mobile-checkout-v1') <> '3c1c8d24c896592878d8b11e64645ce3'
  then raise exception 'golden event set differs from source contract'; end if;
  if not exists (select 1 from cfr_app.detected_cases where workspace_id = 'phase1-golden-a'
      and id = 'case-golden-mobile-checkout' and scenario_hash = '954b0c207c14d28cdd3597626f66aad0924a1e5e4f2583cb51f77d307d568949'
      and content_hash = 'f891a9075e5713ddabe64526cd10a88abce1f53925485130a3abd04ed8555b64')
    or not exists (select 1 from cfr_app.case_signals where workspace_id = 'phase1-golden-a'
      and id = 'signal-golden-mobile-checkout-v1' and content_hash = '5924f293b7be45ff37e218ff95a0ffa501035c3dd03e75ca16a69065adff7c42')
  then raise exception 'golden Case or signal differs from detection contract'; end if;
  if (select count(*) from cfr_app.case_evidence where workspace_id = 'phase1-golden-a'
      and case_id = 'case-golden-mobile-checkout') <> 3
    or (select md5(string_agg(id || ':' || content_hash, '|' order by id))
      from cfr_app.case_evidence where workspace_id = 'phase1-golden-a'
        and case_id = 'case-golden-mobile-checkout') <> '47b09e8c43236f9ad95545ec551051be'
  then raise exception 'golden evidence differs from detection contract'; end if;
  if (select count(*) from cfr_app.case_evidence_event_refs where workspace_id = 'phase1-golden-a') <> 42
    or (select md5(string_agg(evidence_id || ':' || event_id, '|' order by evidence_id, event_id))
      from cfr_app.case_evidence_event_refs where workspace_id = 'phase1-golden-a') <> '4103d52f98155dddffd9eadaadcf7da7'
  then raise exception 'golden evidence references differ from recorded events'; end if;
end $$;

